from typing import List

class Solution:
    def calPoints(self, ops: List[str]) -> int:
        scores = []
        for n in ops:
            if n == "+":
                scores.append(scores[-1] + scores[-2])
            elif n == "D":
                scores.append(scores[-1] * 2)
            elif n == "C":
                scores.pop()
            else:
                scores.append(int(n))
        return sum(scores)

# Input: ops = ["5","2","C","D","+"]
